// MARK: - EngineError

/// A refused command inside an [`EngineEnvelope`]: the [`CommandError`]
/// fields plus its display message.
public struct EngineError: Codable, Equatable, Sendable {
    /// Human-readable message.
    public var message: String
    /// Flattened into the same JSON object (`#[serde(flatten)]`).
    public var commandError: CommandError

    public init(message: String, commandError: CommandError) {
        self.message = message
        self.commandError = commandError
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: GenKey.self)
        message = try c.decode(String.self, forKey: "message")
        commandError = try CommandError(from: decoder)
    }

    public func encode(to encoder: Encoder) throws {
        try commandError.encode(to: encoder)
        var c = encoder.container(keyedBy: GenKey.self)
        try c.encode(message, forKey: "message")
    }
}

