// MARK: - EngineResult

/// Successful result payload inside an [`EngineEnvelope`].
public struct EngineResult: Codable, Equatable, Sendable {
    /// The materialized IR document.
    public var document: EngineJSON
    /// Part metadata per materialized feature.
    public var parts: [EnginePartInfo]
    /// Stable ids of parts consumed by other features.
    public var consumedPartIds: [String]
    /// Non-fatal materialize issues.
    public var warnings: [String]
    /// Stable id of the feature the command created, if any.
    public var createdFeatureId: String?

    public init(document: EngineJSON, parts: [EnginePartInfo], consumedPartIds: [String], warnings: [String], createdFeatureId: String? = nil) {
        self.document = document
        self.parts = parts
        self.consumedPartIds = consumedPartIds
        self.warnings = warnings
        self.createdFeatureId = createdFeatureId
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: GenKey.self)
        document = try c.decode(EngineJSON.self, forKey: "document")
        parts = try c.decode([EnginePartInfo].self, forKey: "parts")
        consumedPartIds = try c.decode([String].self, forKey: "consumedPartIds")
        warnings = try c.decode([String].self, forKey: "warnings")
        createdFeatureId = try c.decodeIfPresent(String.self, forKey: "createdFeatureId")
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: GenKey.self)
        try c.encode(document, forKey: "document")
        try c.encode(parts, forKey: "parts")
        try c.encode(consumedPartIds, forKey: "consumedPartIds")
        try c.encode(warnings, forKey: "warnings")
        try c.encodeIfPresent(createdFeatureId, forKey: "createdFeatureId")
    }
}

// MARK: - FeatureInput

/// Every feature kind and its typed parameters.
///
/// This is THE schema — encoding, decoding, validation, and the WASM API
/// are all derived from this enum.
public enum FeatureInput: Codable, Equatable, Sendable {
    /// - sizeX: Width (X).
    /// - sizeY: Depth (Y).
    /// - sizeZ: Height (Z).
    case cube(sizeX: Double, sizeY: Double, sizeZ: Double)
    /// - radius: Radius.
    /// - height: Height along Z.
    /// - segments: Tessellation segments.
    case cylinder(radius: Double, height: Double, segments: Int? = nil)
    /// - radius: Radius.
    /// - segments: Tessellation segments.
    case sphere(radius: Double, segments: Int? = nil)
    /// - radiusBottom: Bottom radius.
    /// - radiusTop: Top radius (0 for a point).
    /// - height: Height along Z.
    /// - segments: Tessellation segments.
    case cone(radiusBottom: Double, radiusTop: Double, height: Double, segments: Int? = nil)
    /// - booleanType: Union, difference, or intersection.
    /// - inputA: First input feature ID.
    /// - inputB: Second input feature ID.
    case boolean(booleanType: BooleanType, inputA: String, inputB: String)
    /// - sketch: Sketch data (JSON-serialized CsgOp::Sketch2D).
    /// - depth: Extrusion depth.
    /// - direction: Extrusion direction (unit vector).
    /// - twistAngle: Optional twist angle (degrees).
    /// - scaleEnd: Optional end scale factor.
    case extrude(sketch: String, depth: Double, direction: [Double], twistAngle: Double? = nil, scaleEnd: Double? = nil)
    /// - sketch: Sketch data (JSON-serialized CsgOp::Sketch2D).
    /// - axisOrigin: Axis origin point.
    /// - axisDir: Axis direction vector.
    /// - angleDeg: Angle of revolution (degrees).
    case revolve(sketch: String, axisOrigin: [Double], axisDir: [Double], angleDeg: Double)
    /// - sketch: Sketch data (JSON-serialized CsgOp::Sketch2D).
    /// - path: Path curve (JSON-serialized PathCurve).
    /// - twistAngle: Optional twist angle.
    /// - scaleStart: Optional start scale.
    /// - scaleEnd: Optional end scale.
    case sweep(sketch: String, path: String? = nil, twistAngle: Double? = nil, scaleStart: Double? = nil, scaleEnd: Double? = nil)
    /// - profiles: Sketch data for each profile (JSON-serialized CsgOp::Sketch2D).
    /// - closed: Whether the loft is closed (wraps around).
    case loft(profiles: [String], closed: Bool? = nil)
    /// - input: Source feature ID.
    /// - radius: Fillet radius.
    case fillet(input: String, radius: Double)
    /// - input: Source feature ID.
    /// - distance: Chamfer distance.
    case chamfer(input: String, distance: Double)
    /// - input: Source feature ID.
    /// - thickness: Wall thickness.
    case shell(input: String, thickness: Double)
    /// - input: Source feature ID.
    /// - direction: Pattern direction vector.
    /// - count: Number of copies.
    /// - spacing: Spacing between copies.
    case linearPattern(input: String, direction: [Double], count: Int, spacing: Double)
    /// - input: Source feature ID.
    /// - axisOrigin: Axis origin point.
    /// - axisDir: Axis direction vector.
    /// - count: Number of copies.
    /// - angleDeg: Total angle (degrees).
    case circularPattern(input: String, axisOrigin: [Double], axisDir: [Double], count: Int, angleDeg: Double)
    /// - input: Source feature ID.
    /// - plane: Mirror plane ("XY", "XZ", or "YZ").
    case mirror(input: String, plane: String)
    /// - text: The text content.
    /// - height: Font height.
    /// - depth: Extrusion depth.
    /// - alignment: Text alignment ("left", "center", "right").
    /// - letterSpacing: Letter spacing multiplier.
    /// - lineSpacing: Line spacing multiplier.
    case text(text: String, height: Double, depth: Double, alignment: String? = nil, letterSpacing: Double? = nil, lineSpacing: Double? = nil)
    /// - positionsJson: Vertex positions as JSON array of f64.
    /// - indicesJson: Triangle indices as JSON array of u32.
    /// - normalsJson: Vertex normals as JSON array of f64.
    /// - source: Source filename.
    case importedMesh(positionsJson: String, indicesJson: String, normalsJson: String? = nil, source: String? = nil)
    /// - board: Board data (JSON-serialized Pcb).
    case pcbBoard(board: String? = nil)
    /// - design: Design data (JSON-serialized EmbroideryDesign).
    /// - source: Source filename.
    case embroideryPattern(design: String? = nil, source: String? = nil)
    /// - path: Part source path, e.g. `"std:fastener.bolt.socket-head"`.
    /// - version: Pinned version string, e.g. `"1.0"`.
    /// - paramsJson: Parameters as a JSON-serialized object.
    case partInstance(path: String, version: String, paramsJson: String)
    /// - sourceFeature: Source feature ID that defines the geometry.
    /// - name: Optional human-readable name.
    case partDef(sourceFeature: String, name: String? = nil)
    /// - partDef: Part definition feature ID.
    /// - name: Optional name.
    /// - transform: Transform data (JSON-serialized Transform3D).
    case instance(partDef: String, name: String? = nil, transform: String? = nil)
    /// - kind: Joint kind ("Fixed", "Revolute", "Slider", "Cylindrical", "Ball").
    /// - childInstance: Child instance feature ID.
    /// - parentInstance: Parent instance feature ID.
    /// - anchorA: Parent anchor point.
    /// - anchorB: Child anchor point.
    /// - axis: Joint axis (for revolute/slider/cylindrical).
    /// - name: Optional name.
    /// - limits: Joint limits (JSON-serialized JointLimits).
    case joint(kind: String, childInstance: String, parentInstance: String? = nil, anchorA: [Double], anchorB: [Double], axis: [Double]? = nil, name: String? = nil, limits: String? = nil)
    /// - environment: Environment settings (JSON).
    /// - lights: Light definitions (JSON).
    /// - background: Background settings (JSON).
    /// - postProcessing: Post-processing settings (JSON).
    /// - cameraPresets: Camera presets (JSON).
    case sceneSettings(environment: String? = nil, lights: String? = nil, background: String? = nil, postProcessing: String? = nil, cameraPresets: String? = nil)
    /// - title: Sheet title.
    /// - sheet: Sheet data (JSON-serialized SchematicSheet).
    case schematic(title: String? = nil, sheet: String? = nil)
    /// - titleBlock: Title block fields (JSON-serialized `DrawingTitleBlock`).
    /// - sections: Section lines (JSON-serialized `Vec<DrawingSectionLine>`).
    /// - showBom: BOM table visibility (JSON bool).
    case drawingSettings(titleBlock: String? = nil, sections: String? = nil, showBom: String? = nil)
    /// - system: System data (JSON-serialized `MoleculeSystem`).
    case molecule(system: String? = nil)
    /// - studies: Studies data (JSON-serialized `Vec<AnalysisStudy>`).
    case analysisStudies(studies: String? = nil)
    /// - constraints: Constraints data (JSON-serialized `Vec<DesignConstraint>`).
