    /// The `type` discriminator.
    public var type: String {
        switch self {
        case .cube: return "Cube"
        case .cylinder: return "Cylinder"
        case .sphere: return "Sphere"
        case .cone: return "Cone"
        case .boolean: return "Boolean"
        case .extrude: return "Extrude"
        case .revolve: return "Revolve"
        case .sweep: return "Sweep"
        case .loft: return "Loft"
        case .fillet: return "Fillet"
        case .chamfer: return "Chamfer"
        case .shell: return "Shell"
        case .linearPattern: return "LinearPattern"
        case .circularPattern: return "CircularPattern"
        case .mirror: return "Mirror"
        case .text: return "Text"
        case .importedMesh: return "ImportedMesh"
        case .pcbBoard: return "PcbBoard"
        case .embroideryPattern: return "EmbroideryPattern"
        case .partInstance: return "PartInstance"
        case .partDef: return "PartDef"
        case .instance: return "Instance"
        case .joint: return "Joint"
        case .sceneSettings: return "SceneSettings"
        case .schematic: return "Schematic"
        case .drawingSettings: return "DrawingSettings"
        case .molecule: return "Molecule"
