// MARK: - MapPatch

/// Per-key changes to one object-valued document field.
public struct MapPatch: Codable, Equatable, Sendable {
    /// Keys added or changed, with their new values.
    public var set: [String: EngineJSON]
    /// Keys removed.
    public var remove: [String]

    public init(set: [String: EngineJSON], remove: [String]) {
        self.set = set
        self.remove = remove
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: GenKey.self)
        set = try c.decode([String: EngineJSON].self, forKey: "set")
        remove = try c.decode([String].self, forKey: "remove")
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: GenKey.self)
        try c.encode(set, forKey: "set")
        try c.encode(remove, forKey: "remove")
    }
}

// MARK: - MaterialDef

/// PBR material definition.
public struct MaterialDef: Codable, Equatable, Sendable {
    /// Material name (e.g. "aluminum", "abs_white").
    public var name: String
    /// Base color as `[r, g, b]` in 0.0..1.0.
    public var color: [Double]
    /// Metallic factor (0.0 = dielectric, 1.0 = metal).
    public var metallic: Double
    /// Roughness factor (0.0 = mirror, 1.0 = diffuse).
    public var roughness: Double
    /// Density in kg/m^3 (for physics simulation).
    public var density: Double?
    /// Static friction coefficient (for physics simulation).
    public var friction: Double?
    /// Optional physically-based extensions. When `transmission > 0` the
    /// renderer switches to a `MeshPhysicalMaterial` so the part renders as
    /// glass / translucent plastic. The vcode (`.loon`) text format does not
    /// yet round-trip these — they survive the JSON `.vcad` format only.
    public var transmission: Double?
    /// Index of refraction (for transmissive materials).
    public var ior: Double?
    /// Volume thickness for refraction (mm).
    public var thickness: Double?
    /// Distance at which light is attenuated to the attenuation color (mm).
    public var attenuationDistance: Double?
    /// Color light becomes by `attenuationDistance` as `[r, g, b]` in 0.0..1.0.
    public var attenuationColor: [Double]?
    /// Clearcoat layer intensity (0.0..1.0).
    public var clearcoat: Double?
    /// Clearcoat layer roughness (0.0..1.0).
    public var clearcoatRoughness: Double?
    /// Directional bias of the specular highlight, in -1.0..1.0.
    ///
    /// `0` (the default when absent) is an ordinary round highlight.
    /// Positive values stretch it along the surface's own `dP/du` — the
    /// circumferential direction on a cylinder, i.e. the grain a lathe or a
    /// boring bar leaves. Negative values stretch it across. This is what
    /// distinguishes brushed and turned finishes from a uniformly polished
    /// one; it is honoured by the photoreal path tracer, which shades the
    /// analytic BRep and therefore has the exact parameterisation to hand.
    public var anisotropy: Double?

    public init(name: String, color: [Double], metallic: Double, roughness: Double, density: Double? = nil, friction: Double? = nil, transmission: Double? = nil, ior: Double? = nil, thickness: Double? = nil, attenuationDistance: Double? = nil, attenuationColor: [Double]? = nil, clearcoat: Double? = nil, clearcoatRoughness: Double? = nil, anisotropy: Double? = nil) {
        self.name = name
        self.color = color
        self.metallic = metallic
        self.roughness = roughness
        self.density = density
        self.friction = friction
        self.transmission = transmission
        self.ior = ior
        self.thickness = thickness
        self.attenuationDistance = attenuationDistance
        self.attenuationColor = attenuationColor
        self.clearcoat = clearcoat
        self.clearcoatRoughness = clearcoatRoughness
        self.anisotropy = anisotropy
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: GenKey.self)
        name = try c.decode(String.self, forKey: "name")
        color = try c.decode([Double].self, forKey: "color")
        metallic = try c.decode(Double.self, forKey: "metallic")
        roughness = try c.decode(Double.self, forKey: "roughness")
        density = try c.decodeIfPresent(Double.self, forKey: "density")
        friction = try c.decodeIfPresent(Double.self, forKey: "friction")
        transmission = try c.decodeIfPresent(Double.self, forKey: "transmission")
        ior = try c.decodeIfPresent(Double.self, forKey: "ior")
        thickness = try c.decodeIfPresent(Double.self, forKey: "thickness")
        attenuationDistance = try c.decodeIfPresent(Double.self, forKey: "attenuationDistance")
        attenuationColor = try c.decodeIfPresent([Double].self, forKey: "attenuationColor")
        clearcoat = try c.decodeIfPresent(Double.self, forKey: "clearcoat")
        clearcoatRoughness = try c.decodeIfPresent(Double.self, forKey: "clearcoatRoughness")
        anisotropy = try c.decodeIfPresent(Double.self, forKey: "anisotropy")
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: GenKey.self)
        try c.encode(name, forKey: "name")
        try c.encode(color, forKey: "color")
        try c.encode(metallic, forKey: "metallic")
        try c.encode(roughness, forKey: "roughness")
        try c.encodeIfPresent(density, forKey: "density")
        try c.encodeIfPresent(friction, forKey: "friction")
        try c.encodeIfPresent(transmission, forKey: "transmission")
        try c.encodeIfPresent(ior, forKey: "ior")
        try c.encodeIfPresent(thickness, forKey: "thickness")
        try c.encodeIfPresent(attenuationDistance, forKey: "attenuationDistance")
        try c.encodeIfPresent(attenuationColor, forKey: "attenuationColor")
        try c.encodeIfPresent(clearcoat, forKey: "clearcoat")
        try c.encodeIfPresent(clearcoatRoughness, forKey: "clearcoatRoughness")
        try c.encodeIfPresent(anisotropy, forKey: "anisotropy")
    }
}

// MARK: - PartsDelta

/// Which parts a command added, updated or removed, by stable id.
public struct PartsDelta: Codable, Equatable, Sendable {
    /// New parts.
    public var added: [EnginePartInfo]
    /// Parts whose info or geometry (any node in their subtree) changed.
    /// Hosts re-tessellate exactly these plus `added`.
    public var updated: [EnginePartInfo]
    /// Stable ids of parts that no longer exist.
    public var removed: [String]
    /// The full part order (stable ids), present when it changed.
    public var order: [String]?

    public init(added: [EnginePartInfo], updated: [EnginePartInfo], removed: [String], order: [String]? = nil) {
        self.added = added
        self.updated = updated
        self.removed = removed
        self.order = order
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: GenKey.self)
        added = try c.decode([EnginePartInfo].self, forKey: "added")
        updated = try c.decode([EnginePartInfo].self, forKey: "updated")
        removed = try c.decode([String].self, forKey: "removed")
        order = try c.decodeIfPresent([String].self, forKey: "order")
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: GenKey.self)
        try c.encode(added, forKey: "added")
        try c.encode(updated, forKey: "updated")
        try c.encode(removed, forKey: "removed")
        try c.encodeIfPresent(order, forKey: "order")
    }
}

// MARK: - ToolCall

/// An AI tool call as hosts hand it to the engine
/// ([`DocumentApi::apply_tool_envelope`]). `args` stays JSON: each tool
/// lowers its own argument shape in [`crate::tools::lower`].
public struct ToolCall: Codable, Equatable, Sendable {
    /// Tool name (`create`, `translate`, `place`, …).
    public var tool: String
    /// Tool arguments (a JSON object).
    public var args: [String: EngineJSON]

    public init(tool: String, args: [String: EngineJSON]) {
        self.tool = tool
        self.args = args
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: GenKey.self)
        tool = try c.decode(String.self, forKey: "tool")
        args = try c.decode([String: EngineJSON].self, forKey: "args")
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: GenKey.self)
        try c.encode(tool, forKey: "tool")
        try c.encode(args, forKey: "args")
    }
}
